// Copies the built frontend (apps/web/dist) into a TypeScript module the Worker imports.
// Why not Workers static assets? Static asset uploads use a separate upload token that some
// deploy environments (including the cloud sandbox this was built in) cannot send, so the app
// is bundled into the Worker script instead. Same result: one Worker serves the app and /api.
// Run by `npm run build:web`. The output file is generated; do not edit it by hand.

import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { extname, join, relative } from "node:path";

const ROOT = join(import.meta.dirname, "..");
const DIST = join(ROOT, "apps/web/dist");
const OUT = join(ROOT, "workers/app/src/web-assets.generated.ts");

const TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".json": "application/json",
  ".txt": "text/plain; charset=utf-8",
  ".webmanifest": "application/manifest+json",
  ".png": "image/png",
  ".ico": "image/x-icon",
  ".woff2": "font/woff2",
};
const BINARY = new Set([".png", ".ico", ".woff2"]);

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}

const files: Record<string, { type: string; body: string; base64: boolean }> = {};
for (const file of walk(DIST)) {
  const ext = extname(file);
  const path = "/" + relative(DIST, file).split("\\").join("/");
  const base64 = BINARY.has(ext);
  files[path] = {
    type: TYPES[ext] ?? "application/octet-stream",
    body: readFileSync(file).toString(base64 ? "base64" : "utf8"),
    base64,
  };
}
if (!files["/index.html"]) throw new Error("apps/web/dist/index.html is missing. Run the Vite build first.");

writeFileSync(
  OUT,
  `// GENERATED by scripts/embed-web.ts from apps/web/dist. Do not edit.\n` +
    `export const WEB_ASSETS: Record<string, { type: string; body: string; base64: boolean }> = ${JSON.stringify(files)};\n`,
);
console.log(`Embedded ${Object.keys(files).length} files into workers/app/src/web-assets.generated.ts`);
